    container-type: inline-size;
    display: grid;
    gap: var(--column-gap);
    grid-template-columns: 1fr auto 1fr;
    inline-size: 100%;
    margin-inline: auto;
    max-inline-size: var(--main-width);
    outline: none;
    overflow-x: auto;
    overflow-y: hidden;
    position: relative;
"
}

